pub fn binary_search(a: &[i32], key: i32) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = a.len(); // hi is exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < key {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    lo
}

